#include <iostream>
using namespace std;

class FishBox {
    int* p;
public:
    FishBox(int v) { p = new int(v); }

    FishBox(const FishBox& other) {
        p = new int(*other.p);
    }

    ~FishBox() { delete p; }
    int get() const { return *p; }
    void set(int v) { *p = v; }
};

